mapper.select:
SELECT
    (SELECT COUNT(*) FROM tryon_tasks

    )
    +
    (SELECT COUNT(*) FROM gemini_image_tasks

    )
    +
    (SELECT COUNT(*) FROM model_video_tasks

    )

SELECT * FROM ( SELECT 'tryon' AS record_source, id, user_id, status, IFNULL(NULLIF(TRIM(provider), ''), '—') AS task_label, category AS detail_tag, consume_credits, created_at FROM tryon_tasks
UNION ALL SELECT 'gemini_image', id, user_id, status, IFNULL(NULLIF(TRIM(task_type), ''), '—') AS task_label, NULL AS detail_tag, consume_credits, created_at FROM gemini_image_tasks
UNION ALL SELECT 'model_video', id, user_id, status, 'model_video' AS task_label, NULLIF(TRIM(CONCAT(IFNULL(resolution, ''), ' ', IFNULL(aspect_ratio, ''))), '') AS detail_tag, consume_credits, created_at FROM model_video_tasks
) u ORDER BY u.created_at DESC LIMIT #{offset}, #{limit}
